'use strict';

const assert = require('node:assert');
const { describe, it } = require('node:test');
const fs = require('node:fs');
const path = require('node:path');
const { spawnSync } = require('node:child_process');

const SCHEMA = require('../wled00/data/held/schema.js');
const HeldExpr = require('../wled00/data/held/expr.js');
const HeldEngine = require('../wled00/data/held/engine.js');

const FPS = 40;
const run = (e, seconds) => { for (let f = 0; f < seconds * FPS; f++) e.tick(1 / FPS); };
const frame = (e, s = 0) => { const b = new Float64Array(3 * e.strips[s].leds); e.render(s, b); return b; };
const quiet = () => {
  // heartbeat only, no smoothing: makes the output easy to reason about
  const e = new HeldEngine();
  e.setParams({ ambient: { enabled: 0 }, global: { levelSmoothing: 0 } });
  return e;
};

describe('Held schema matches the firmware param tables', () => {
  const src = fs.readFileSync(path.join(__dirname, '../wled00/held/held_params.h'), 'utf8');
  const TYPES = { f: 'FLOAT', i: 'INT', b: 'BOOL', e: 'ENUM', c: 'COLOR' };
  const table = (macro) => {
    const body = src.split('#define ' + macro + '(X)')[1].split(/\n\s*\n|#define/)[0];
    return [...body.matchAll(/X\(\s*(\w+),\s*(\w+),\s*(\d),\s*([^,]+),\s*([^,]+),\s*([^,]+),\s*([^)]+)\)/g)]
      .map((m) => ({ k: m[1], t: m[2], r: m[3] === '1', min: Number(m[4]), max: Number(m[5]), d0: Number(m[6]), d1: Number(m[7]) }));
  };
  const compare = (macro, defs) => {
    const c = table(macro);
    assert.deepStrictEqual(c.map((p) => p.k), defs.map((p) => p.k), macro + ': keys/order differ');
    defs.forEach((p, i) => {
      const q = c[i], ranged = Array.isArray(p.d);
      const d0 = ranged ? p.d[0] : p.d, d1 = ranged ? p.d[1] : p.d;
      assert.deepStrictEqual([q.t, q.r, q.min, q.max, q.d0, q.d1], [TYPES[p.t], ranged, p.min, p.max, d0, d1], `${macro}.${p.k} differs`);
    });
  };
  it('global', () => compare('HELD_GLOBAL_PARAMS', SCHEMA.global));
  it('strip', () => compare('HELD_STRIP_PARAMS', SCHEMA.strip));
  for (const [macro, key] of [['HELD_HEARTBEAT_PARAMS', 'heartbeat'], ['HELD_AMBIENT_PARAMS', 'ambient'], ['HELD_PIECEIN_PARAMS', 'pieceIn'], ['HELD_PIECEOUT_PARAMS', 'pieceOut'], ['HELD_ALLIN_PARAMS', 'allIn']]) {
    it(key, () => compare(macro, SCHEMA.layerByKey[key].p));
  }
  it('every event layer has "enabled" first (the firmware relies on it)', () => {
    for (const L of SCHEMA.layers) assert.strictEqual(L.p[0].k, 'enabled', L.k);
  });
});

describe('Held engine', () => {
  it('emits heartbeat pulses at the configured BPM', () => {
    const e = quiet();
    e.setParams({ heartbeat: { bpm: 60, pulseSpeed: 1 } });
    run(e, 10.05);
    // phase starts at 0.9 -> first beat after 0.1 s, then one per second
    assert.strictEqual(e.hbPulses.length, 10);
    for (let i = 1; i < e.hbPulses.length; i++) assert.ok(Math.abs(e.hbPulses[i - 1] - e.hbPulses[i] - 1) < 1e-6);
  });

  it('pulses stop at the antipode and wrap across the strip ends', () => {
    const e = quiet();
    e.setStrips([{ leds: 120, origin: 5 }]);
    const base = frame(e);  // before any pulse
    let nearOrigin = 0, wrapped = 0, antipode = 0;
    for (let f = 0; f < 12 * FPS; f++) {
      e.tick(1 / FPS);
      const b = frame(e);
      nearOrigin = Math.max(nearOrigin, Math.abs(b[3 * 10] - base[3 * 10]));
      wrapped = Math.max(wrapped, Math.abs(b[3 * 117] - base[3 * 117]));  // reached going backwards across LED 0
      antipode = Math.max(antipode, Math.abs(b[3 * 65] - base[3 * 65]));   // origin + 60
    }
    assert.ok(nearOrigin > 0.05, 'pulses visible near the origin');
    assert.ok(wrapped > 0.05, 'backward pulses wrap past LED 0');
    assert.ok(antipode < 1e-9, 'nothing reaches the antipode');
  });

  it('direction "forward" leaves the backward side at baseline', () => {
    const e = quiet();
    e.setParams({ heartbeat: { direction: 1 } });
    const base = frame(e);
    let back = 0;
    for (let f = 0; f < 8 * FPS; f++) { e.tick(1 / FPS); back = Math.max(back, Math.abs(frame(e)[3 * 110] - base[3 * 110])); }
    assert.ok(back < 1e-9);
  });

  it('repetitions tile the whole composited pattern (repeat and mirror)', () => {
    for (const mirror of [0, 1]) {
      const e = new HeldEngine();   // all layers on, plus an event
      e.setStrips([{ leds: 120, origin: 10, reps: 3, mirror: mirror }]);
      e.setPieces(0b111111);
      run(e, 5);
      const b = frame(e), V = 40, at = (d) => 3 * ((10 + d + 1200) % 120);
      for (let t = 0; t < V; t++) {
        for (let c = 0; c < 3; c++) {
          if (mirror) assert.ok(Math.abs(b[at(V + t) + c] - b[at(V - t) + c]) < 1e-12, `mirror about copy boundary, t=${t}`);
          else assert.strictEqual(b[at(t) + c], b[at(V + t) + c], `repeat, t=${t}`);
          assert.strictEqual(b[at(t) + c], b[at(2 * V + t) + c], 'copies 0 and 2 run the same way');
        }
      }
    }
  });

  it('pieces drive the level and the right events', () => {
    const e = quiet();
    e.setPieces(0b1);
    assert.deepStrictEqual(e.events.map((v) => v.type), ['pieceIn']);
    run(e, 0.1);
    assert.ok(Math.abs(e.level - 0.2) < 1e-9, 'one of six pieces = level 0.2');
    e.clearEvents();
    e.setPieces(0b111111);
    assert.deepStrictEqual(e.events.map((v) => v.type), ['allIn'], 'last piece plays allIn, not pieceIn');
    e.setPieces(0b011111);
    assert.deepStrictEqual(e.events.map((v) => v.type), ['allIn', 'pieceOut']);
    assert.ok(e.events[0].cancelAge >= 0, 'allIn is cancelled when a piece is pulled');
    run(e, 3);
    assert.strictEqual(e.events.length, 0, 'events expire');
    e.setParams({ global: { autoEvents: 0 } });
    e.setPieces(0);
    assert.strictEqual(e.events.length, 0, 'autoEvents off: no events');
  });

  it('the last-piece sequence runs to completion and hands back to the base state', () => {
    const e = quiet();
    e.setPieces(0b111111);
    const P = e.R.allIn;
    const end = P.pulseStart + P.pulseDuration + P.holdDuration + P.beatCount * 60 / P.beatBpm;
    run(e, P.pulseStart + P.pulseDuration + 0.5);
    const hold = frame(e);
    const solid = [0xFF / 255, 0x6A / 255, 0x2A / 255];
    for (let c = 0; c < 3; c++) assert.ok(Math.abs(hold[c] - solid[c]) < 0.02, 'holds the solid colour');
    run(e, end - (P.pulseStart + P.pulseDuration + 0.5) + 0.1);
    assert.strictEqual(e.events.length, 0);
  });

  it('is deterministic and stays finite and in range under random params', () => {
    const rnd = (() => { let s = 12345; return () => (s = (s * 1103515245 + 12345) % 2147483648) / 2147483648; })();
    const randomParams = () => {
      const out = {};
      for (const L of SCHEMA.layers.concat([{ k: 'global', p: SCHEMA.global }])) {
        out[L.k] = {};
        for (const p of L.p) {
          const v = () => p.min + (p.max - p.min) * rnd();
          out[L.k][p.k] = (p.t === 'f' || p.t === 'i') && rnd() < 0.3 ? [v(), v()] : v();
        }
        if (L.k !== 'global') out[L.k].enabled = 1;
      }
      out.global.numPieces = 6;
      return out;
    };
    for (let trial = 0; trial < 6; trial++) {
      const params = randomParams();
      const strips = [{ leds: 1 + Math.floor(rnd() * 200), origin: rnd() * 100, reps: 1 + Math.floor(rnd() * 4), mirror: rnd() < 0.5 ? 1 : 0 }, { leds: 1 + Math.floor(rnd() * 60) }];
      const a = new HeldEngine(), b = new HeldEngine();
      for (const e of [a, b]) { e.setStrips(strips); e.setParams(params); }
      for (let f = 0; f < 30 * FPS; f++) {
        if (f % 37 === 0) { const m = Math.floor(rnd() * 64); a.setPieces(m); b.setPieces(m); }
        a.tick(1 / FPS); b.tick(1 / FPS);
        if (f % 5) continue;
        for (let s = 0; s < 2; s++) {
          const fa = frame(a, s), fb = frame(b, s);
          for (let j = 0; j < fa.length; j++) {
            assert.ok(Number.isFinite(fa[j]) && fa[j] >= 0 && fa[j] <= 1, `trial ${trial} value ${fa[j]}`);
            assert.strictEqual(fa[j], fb[j]);
          }
        }
      }
    }
  });

  it('sanitises incoming params', () => {
    const e = new HeldEngine();
    e.setParams({ heartbeat: { bpm: 9999, color: '#00ff00', pulseWidth: [4, 8], shape: [2, 1], opacity: 'x' }, nope: { a: 1 } });
    const H = e.params.heartbeat;
    assert.deepStrictEqual(H.bpm, 200, 'clamped; a plain number is not ranged');
    assert.strictEqual(H.color, 0x00ff00);
    assert.deepStrictEqual(H.pulseWidth, [4, 8], 'any numeric param can be ranged');
    assert.strictEqual(H.shape, 2, 'enums are never ranged');
    assert.strictEqual(H.opacity, 1, 'garbage falls back to the default');
  });
});

describe('Held parameter expressions', () => {
  const ev = (src, vars = [3, 2, 0.5, 0.6, 6]) => { const c = HeldExpr.compile(src); assert.ok(!c.error, c.error); return c.prog.eval(vars); };
  it('evaluates JS-style expressions', () => {
    assert.strictEqual(ev('1 + 2 * 3 ** 2'), 19);
    assert.strictEqual(ev('-2 ** 2'), -4);
    assert.strictEqual(ev('pieces > 2 && t < 5 ? 10 : 20'), 10);
    assert.strictEqual(ev('!(pieces > 2) || 7'), 7);
    assert.strictEqual(ev('7 % 3 + mod(-1, 3)'), 3);
    assert.ok(Math.abs(ev('Math.sin(PI / 2) + wave(0.25) + triangle(0.5) + square(0.2)') - 4) < 1e-12);
    assert.strictEqual(ev('lerp(45, 70, level)'), 60);
    assert.strictEqual(ev('clamp(min(5, 2, 9), 3, 4) + max(1, 8)'), 11);
  });
  it('supports arrow headers (renamed positionally) and let/return blocks', () => {
    assert.strictEqual(ev('(n, time, e, lv) => n * 100 + time * 10 + e'), 320.5);
    assert.strictEqual(ev('x => x + numPieces'), 9);
    assert.strictEqual(ev('(pieces, t) => { let a = pieces * 2; const b = a + t; return b * 10; } // done'), 80);
  });
  it('rejects anything the firmware could not run', () => {
    for (const [src, msg] of [['foo(1)', /unknown function/], ['bar + 1', /unknown name/], ['1 +', /unexpected end/],
      ['sin(1, 2)', /takes 1 argument/], ['for (;;) {}', /unexpected|unknown/], ['a = 1', /unknown name|unexpected/],
      ['{ let a = 1; }', /expected let, const or return/], ['1 2', /unexpected text/], ['x'.repeat(401), /too long/]]) {
      const c = HeldExpr.compile(src);
      assert.ok(c.error && msg.test(c.error), `${src} -> ${c.error}`);
    }
  });
  it('drives engine params, with event time for event layers', () => {
    const e = quiet();
    e.setParams({ heartbeat: { bpm: '(pieces, t) => 60 + 30 * t' }, pieceIn: { width: '(p, t, et) => 2 + 10 * et' } });
    run(e, 1);
    assert.ok(Math.abs(e.R.heartbeat.bpm - 90) < 1e-9);
    e.trigger('pieceIn');
    run(e, 0.5);
    e.state();   // resolves per event
    assert.ok(Math.abs(e.R.pieceIn.width - 7) < 1e-9, 'et = event age');
    e.setParams({ heartbeat: { bpm: '1e9' } });
    run(e, 0.1);
    assert.strictEqual(e.R.heartbeat.bpm, 200, 'results are clamped');
  });
  it('keeps the previous value when an expression is invalid, and never on globals', () => {
    const e = new HeldEngine();
    e.setParams({ heartbeat: { bpm: 'nope(' }, global: { numPieces: 'pieces' } });
    assert.deepStrictEqual(e.params.heartbeat.bpm, [45, 70]);
    assert.ok(e.exprErrors['heartbeat.bpm']);
    assert.strictEqual(typeof e.params.global.numPieces, 'number');
  });
});

describe('Held release grace and noise pan', () => {
  it('ignores piece removal near the end of the last-piece animation', () => {
    const e = quiet();
    e.setPieces(0b111111);
    const ai = e.events[0];
    e.setPieces(0b011111);
    assert.ok(ai.cancelAge >= 0, 'early removal still cancels');
    e.clearEvents();
    e.setPieces(0b111111);   // complete again -> new animation
    const P = e.R.allIn;
    const dur = P.pulseStart + P.pulseDuration + P.holdDuration + P.beatCount * 60 / P.beatBpm;
    run(e, dur - P.releaseGrace + 0.5);
    e.setPieces(0b000111);
    assert.deepStrictEqual(e.events.map((v) => [v.type, v.cancelAge]), [['allIn', -1]], 'no pieceOut, not cancelled');
    run(e, 0.5);
    assert.ok(e.level < 1, 'level still follows the pieces');
    const age = e.events[0].age;
    e.setPieces(0b111111);
    assert.strictEqual(e.events.length, 1);
    assert.strictEqual(e.events[0].age, age, 'completing again does not restart it');
  });
  it('pans the noise along the strip', () => {
    const e = new HeldEngine();
    e.setParams({ heartbeat: { enabled: 0 }, ambient: { twinkleRate: 0, noiseSpeed: 0, noisePan: 10, noiseAmount: 1, noiseThreshold: 0, blend: 1 } });
    run(e, 1);
    const a = frame(e);
    run(e, 1);
    const b = frame(e);
    for (let i = 10; i < 120; i++) assert.ok(Math.abs(b[3 * i] - a[3 * (i - 10)]) < 1e-9, `led ${i}`);
  });
});

